package com.mo.economy_system.target.neoforge1211.protocol;import static org.junit.jupiter.api.Assertions.*;import com.mo.economy_system.common.network.*;import io.netty.buffer.Unpooled;import java.util.UUID;import net.minecraft.core.RegistryAccess;import net.minecraft.network.RegistryFriendlyByteBuf;import org.junit.jupiter.api.Test;
class NeoForge1211DeliverDemandOrderProtocolTest{@Test void codecRoundTripsAt14(){var m=new DeliverDemandOrderMessage(UUID.randomUUID());var b=new RegistryFriendlyByteBuf(Unpooled.buffer(),RegistryAccess.EMPTY);var c=NeoForge1211MessageCodecs.codec(EconomyMessages.DELIVER_DEMAND_ORDER);c.encode(m,b);assertEquals(m,c.decode(b));assertEquals(14,EconomyMessages.DELIVER_DEMAND_ORDER.discriminator());}@Test void nullRejected(){assertThrows(NullPointerException.class,()->new DeliverDemandOrderMessage(null));}}
